      // @knowledge e2dd6d8b-8d5c-4354-96cd-206d3200a43f@8789c8882e1fa4e8
      status = p.status,
      // @knowledge b733a35f-4f16-4a7d-bcef-58c29d3e6c64@ab4023677caa4ee6
      projectId = IdConv.fromProto(p.projectId),
      // @knowledge 63486008-3eaf-40c0-b1ab-d208abe2222d@b741e069057c3a93
      version = p.version,
      // @knowledge 76948d2d-1250-4957-b7af-a4d11115271b@c6634b9448fd2316
      baseVersion = p.baseVersion,
      // @knowledge dd7d2d28-1e8e-47dc-b5df-600a5c9bffe8@31696ccb9c156258
      patchSessionIds = p.patchSessionIds.map(IdConv.fromProto).toList,
      // @knowledge 7a1aefa3-68ad-42fb-ac07-a08abd8ad5b2@7d5d519d3760ebe7
      knowledgePackages = p.knowledgePackages,
      // @knowledge 63ab6a2f-1d9e-4f44-91e4-44a3b2c9b2fd@b6721e74254286ca
      stateHash = p.stateHash,
      // @knowledge e81dec16-315f-4420-a623-d17fa5118715@00611536fb092d2a
      headPatchId = IdConv.fromProto(p.headPatchId),
      // @knowledge 521a6a9b-919e-49c2-83dc-7449bb84ba58@200aa9f35367a49a
      headPatchHash = p.headPatchHash,
      // @knowledge 3dcf06f2-cf88-4afd-8301-53ec06af493e@47b0c1ece338a13d
      conflicts = p.conflicts.map(CatalogConflictConv.fromProto).toList,
      // @knowledge 06409b3f-ef12-4b1e-8686-610cb8af525c@fed2720ed2f935c2
      assembledAt = InstantConv.fromProto(p.assembledAt),
      // @knowledge 4b43c474-0750-42c1-bb4d-117adc4ae192@eff3e643dd9a096a
      assembledBy = p.assembledBy,
      // @knowledge 1e99fa37-9c79-44ca-bf23-f1cccd35b963@3948b3d80f51d872
      exportedAt = InstantConv.fromProto(p.exportedAt),
      // @knowledge 21665ef6-7331-4399-92eb-acd99f9a7dc2@d1efdfd31a27242a
      exportedBy = p.exportedBy,
      // @knowledge c35771e2-11cd-408b-83cb-41abafabe2f5@33c381cc884d5714
      releasedAt = InstantConv.fromProto(p.releasedAt),
      // @knowledge bfbc869c-d676-47d8-9e17-6a7dbb3c4502@f91dbfb2e4521109
      releasedBy = p.releasedBy,
      // @knowledge 5b8a6c5a-fe5b-4b03-81e6-2b02fa88c5ce@656e817ab53882c3
      conceptIndex = p.conceptIndex.map(ConceptIndexEntryConv.fromProto).toList
    )
  }


  object ListConv {
    def toProto[D, P](domain: List[D])(implicit c: ProtoConverter[D, P]): Seq[P] = domain.map(c.toProto)
    def fromProto[D, P](proto: Seq[P])(implicit c: ProtoConverter[D, P]): List[D] = proto.map(c.fromProto).toList
  }

  object InstantConv {
    def toProto(domain: java.time.Instant): Long = Option(domain).fold(0L)(_.toEpochMilli)
    def fromProto(proto: Long): java.time.Instant = java.time.Instant.ofEpochMilli(proto)
  }

}

/** S2-82-B3（2026-09-11）：self-companion——trait 嵌套 Conv object 的静态寻址口。
  * Scala trait 无 term（TraitName.NestedObject 编译红「no companion object」）——
  * 投影 handler/读端经 ModelCatalogProtoConverters.XxxConv.fromProto 静态调用需要本伴生；
  * EventAdapter/SnapshotAdapter 等 mixin 消费方不受影响（trait 本体原样）。 */
object ModelCatalogProtoConverters extends ModelCatalogProtoConverters
